func (w *Window) Invalidate() {
	if w == nil {
		return
	}
	w.Invalidated = true

	for _, vp := range w.viewports {
		if vp != nil {
			vp.Invalidated = true
		}
	}

	for _, child := range w.children {
		if child != nil {
			child.Invalidated = true
		}
	}

	if w.owner != nil {
		w.owner.Invalidated = true
	}
}

